<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Products | Lab 5</title><style>body{font-family:Arial,sans-serif;margin:0;color:#172033;background:#f8fafc}.wrap{max-width:1100px;margin:auto;padding:2rem 1rem}header{display:flex;justify-content:space-between;align-items:center;gap:1rem;flex-wrap:wrap}.button,button{display:inline-block;padding:.65rem .9rem;border:0;border-radius:6px;background:#1769e0;color:#fff;text-decoration:none;font-weight:600;cursor:pointer}.muted{color:#667085}table{width:100%;border-collapse:collapse;background:#fff;margin-top:1.5rem;box-shadow:0 5px 20px #0000000d}th,td{padding:.85rem;text-align:left;border-bottom:1px solid #e5e7eb}th{background:#172033;color:#fff}.actions{white-space:nowrap}.danger{background:#b42318}form.inline{display:inline}</style></head><body><div class="wrap"><header><div><p class="muted">Laboratory Exercise No. 5</p><h1>Product Management</h1></div><div><a class="button" href="<?= html_escape(site_url('products/create')); ?>">Add product</a><form class="inline" method="post" action="<?= html_escape(site_url('logout')); ?>"><input type="hidden" name="csrf_token" value="<?= html_escape($csrf_token); ?>"><button type="submit">Log out</button></form></div></header><?php if (empty($products)): ?><p class="muted">No products yet. Add your first product.</p><?php else: ?><table><thead><tr><th>Product</th><th>Description</th><th>Price</th><th>Quantity</th><th>Created</th><th>Actions</th></tr></thead><tbody><?php foreach($products as $product): ?><tr><td><?= html_escape($product['product_name']); ?></td><td><?= html_escape($product['description']); ?></td><td><?= html_escape(number_format((float)$product['price'],2)); ?></td><td><?= html_escape($product['quantity']); ?></td><td><?= html_escape($product['created_at']); ?></td><td class="actions"><a class="button" href="<?= html_escape(site_url('products/edit/'.$product['id'])); ?>">Edit</a> <a class="button danger" href="<?= html_escape(site_url('products/delete/'.$product['id'])); ?>">Delete</a></td></tr><?php endforeach; ?></tbody></table><?php endif; ?><p class="muted"><a href="<?= html_escape(site_url('student')); ?>">Student page</a> · <a href="<?= html_escape(site_url('users')); ?>">Lab 4 users</a></p></div></body></html>
